{"packet_id":"D007-01","doc_id":"D007","jurisdiction":"CA","category":"security_deposits","lifecycle":"enacted","title":"California security deposit cap (AB 12)","requirement":"A landlord may charge no more than one month's rent as a security deposit; small owners of two rental properties with no more than four units total may charge up to two months'. The deposit must be returned within 21 days with an itemized statement.","key_value":"1 month's rent (2 months for small owners)","coverage_conditions":"All residential tenancies; landlords owning only two rental properties with no more than four residential units total (natural persons, family trusts, or LLCs of natural persons) may charge two months' rent.","applicability":{"conditions":[{"type":"owner","role":"exempt","who":"small landlord owning only two rental properties with no more than four residential units total","unit_limit":4}],"per_tenancy":"Photograph requirement applies to tenancies beginning on or after July 1, 2025.","coverage_quotes":["landlords who own only two rental properties with no more than four residential units total can charge up to two months' rent for furnished and unfurnished units if ownership is held by a natural person, family trust, or limited liability company (LLC) where all members are natural persons"]},"exemptions":"Small landlords owning only two rental properties with no more than four residential units total may charge up to two months' rent; first month's rent is not part of the deposit.","penalty":null,"effective_date":"2024-07-01","valid_through":null,"citation":"AB 12","quoted_span":"Starting July 1, 2024, many landlords may only charge one month's rent for unfurnished and furnished units","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D007-01","doc_id":"D007","jurisdiction":"Berkeley, CA","category":"security_deposits","lifecycle":"enacted","title":"Berkeley Rent Ordinance security deposit interest","requirement":"Landlords of units fully or partially covered by Berkeley's Rent Ordinance must pay tenants interest on their security deposit at the end of each year, and a prorated amount if the tenant moves out before the end of the year.","key_value":null,"coverage_conditions":"Units fully or partially covered by Berkeley's Rent Ordinance.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"For tenancies in units fully or partially covered by Berkeley's Rent Ordinance, landlords must pay tenants interest on their security deposit at the end of each year and a prorated amount if the tenant moves out before the end of the year.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D007-01","n_rules":2,"note":null}

